const listPurchases = `-- name: ListPurchases :many
SELECT p.id, p.purchase_no, p.supplier_id, s.name AS supplier_name, p.status, COALESCE(p.invoice_ref, '')::text AS invoice_ref, COALESCE(p.note, '')::text AS note,
       p.location_id, COALESCE(l.name, '')::text AS location_name, p.created_at, p.received_at::timestamptz AS received_at,
       (SELECT count(*) FROM purchase_items i WHERE i.purchase_id = p.id)::bigint AS line_count,
       (SELECT COALESCE(sum(i.entered_qty * i.unit_cost_cents), 0) FROM purchase_items i WHERE i.purchase_id = p.id)::bigint AS total_cents
FROM purchases p JOIN suppliers s ON s.id = p.supplier_id LEFT JOIN stock_locations l ON l.id = p.location_id
WHERE ($1::text = '' OR p.status = $1::text)
  AND ($2::bigint = 0 OR p.supplier_id = $2::bigint)
  AND ($3::bigint = 0 OR p.id < $3::bigint)
ORDER BY p.id DESC LIMIT $4::int
`

type ListPurchasesParams struct {
	Status     string
	SupplierID int64
	BeforeID   int64
	RowLimit   int32
}

type ListPurchasesRow struct {
	ID           int64
	PurchaseNo   int64
	SupplierID   int64
	SupplierName string
	Status       string
	InvoiceRef   string
	Note         string
	LocationID   pgtype.Int8
	LocationName string
	CreatedAt    pgtype.Timestamptz
	ReceivedAt   pgtype.Timestamptz
	LineCount    int64
	TotalCents   int64
}

func (q *Queries) ListPurchases(ctx context.Context, arg ListPurchasesParams) ([]ListPurchasesRow, error) {
	rows, err := q.db.Query(ctx, listPurchases,
		arg.Status,
		arg.SupplierID,
		arg.BeforeID,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListPurchasesRow
	for rows.Next() {
		var i ListPurchasesRow
		if err := rows.Scan(
			&i.ID,
			&i.PurchaseNo,
			&i.SupplierID,
			&i.SupplierName,
			&i.Status,
			&i.InvoiceRef,
			&i.Note,
			&i.LocationID,
			&i.LocationName,
			&i.CreatedAt,
			&i.ReceivedAt,
			&i.LineCount,
			&i.TotalCents,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

