const lockItems = `-- name: LockItems :many
SELECT id, name, active FROM inventory_items WHERE id = ANY($1::bigint[]) ORDER BY id FOR UPDATE
`

type LockItemsRow struct {
	ID     int64
	Name   string
	Active bool
}

// Takes the item's row so two stock changes to the same item take turns. Always lock items in id order (no deadlocks).
func (q *Queries) LockItems(ctx context.Context, dollar_1 []int64) ([]LockItemsRow, error) {
	rows, err := q.db.Query(ctx, lockItems, dollar_1)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []LockItemsRow
	for rows.Next() {
		var i LockItemsRow
		if err := rows.Scan(&i.ID, &i.Name, &i.Active); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockPurchase = `-- name: LockPurchase :one
SELECT id, status FROM purchases WHERE id = $1 FOR UPDATE
`

